"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { X } from "lucide-react";
import { useCart } from "@/lib/cart/context";
import { flags } from "@/lib/config/store.config";
import { useMobileChromeFlag } from "@/lib/mobile-chrome";
import { useMotionReady } from "@/lib/motion";
import {
  pickNextToast,
  progressKey,
  rand,
  nudgeViewers,
  randViewersLt,
  sliceLine,
  type ToastSlice,
} from "@/lib/social-proof";

const SPRING = "cubic-bezier(0.22, 1, 0.36, 1)";

export function SocialProofToast() {
  const cart = useCart();
  const motionReady = useMotionReady();
  const [dismissed, setDismissed] = useState(false);
  const [visible, setVisible] = useState(false);
  const [slice, setSlice] = useState<ToastSlice | null>(null);
  const [displayMs, setDisplayMs] = useState(3000);
  const [phase, setPhase] = useState<"in" | "out">("in");
  const [viewerCount, setViewerCount] = useState(() => randViewersLt());
  const [lineNow, setLineNow] = useState(() => Date.now());

  const startTimerRef = useRef<number | null>(null);
  const phaseOutTimerRef = useRef<number | null>(null);
  const afterOutTimerRef = useRef<number | null>(null);
  const pauseTimerRef = useRef<number | null>(null);
  const lastShownKindRef = useRef<ToastSlice["kind"] | null>(null);

  const eligible = flags.ENABLE_SOCIAL_PROOF && !dismissed && !cart.drawerOpen && motionReady;

  const clearCarouselTimersOnly = useCallback(() => {
    [startTimerRef, phaseOutTimerRef, afterOutTimerRef, pauseTimerRef].forEach((r) => {
      if (r.current !== null) {
        window.clearTimeout(r.current);
        r.current = null;
      }
    });
  }, []);

  useEffect(() => {
    if (!eligible) return undefined;
    const id = window.setInterval(() => {
      setViewerCount((current) => nudgeViewers(current));
    }, 9000);
    return () => window.clearInterval(id);
  }, [eligible]);

  useEffect(() => {
    if (!eligible || !visible || slice?.kind !== "package") return undefined;
    const id = window.setInterval(() => setLineNow(Date.now()), 60_000);
    return () => window.clearInterval(id);
  }, [eligible, visible, slice?.kind]);

  useEffect(() => {
    if (!eligible) {
      lastShownKindRef.current = null;
      clearCarouselTimersOnly();
      setVisible(false);
      setSlice(null);
      setPhase("in");
      return undefined;
    }

    let cancelled = false;

    const showStep = () => {
      if (cancelled) return;
      const displayFor = rand(4200, 5200);
      const pauseAfter = rand(1600, 2800);
      const fadeMs = 480;

      const next = pickNextToast(lastShownKindRef.current);
      lastShownKindRef.current = next.kind;
      setDisplayMs(displayFor);
      setSlice(next);
      setLineNow(Date.now());
      setPhase("in");
      setVisible(true);

      const fadeOutStart = Math.max(120, displayFor - fadeMs);
      phaseOutTimerRef.current = window.setTimeout(() => {
        if (cancelled) return;
        setPhase("out");
        afterOutTimerRef.current = window.setTimeout(() => {
          if (cancelled) return;
          setVisible(false);
          pauseTimerRef.current = window.setTimeout(showStep, pauseAfter);
        }, fadeMs);
      }, fadeOutStart);
    };

    clearCarouselTimersOnly();
    startTimerRef.current = window.setTimeout(showStep, 1200);

    return () => {
      cancelled = true;
      clearCarouselTimersOnly();
    };
  }, [eligible, clearCarouselTimersOnly]);

  const handleDismiss = () => {
    setDismissed(true);
    setVisible(false);
    clearCarouselTimersOnly();
  };

  if (!eligible) return null;

  const lineShown = slice ? sliceLine(slice, viewerCount, lineNow) : "";
  const pk = progressKey(slice, displayMs);

  return (
    <div
      role="status"
      aria-live="polite"
      className="social-proof-toast pointer-events-none fixed left-2.5 z-[45] w-max max-w-[calc(100vw-1.25rem)] transition-[opacity,transform] duration-500 sm:left-4"
      style={{
        pointerEvents: visible ? "auto" : "none",
        opacity: visible ? 1 : 0,
        transform: visible ? "translateY(0)" : "translateY(12px)",
        transitionTimingFunction: SPRING,
      }}
    >
      <div className="social-proof-shell relative overflow-hidden rounded-full border border-gold-400/40 shadow-card">
        <div className="flex shrink-0 items-center gap-2 py-2.5 pl-2.5 pr-1.5 sm:gap-2.5 sm:py-3 sm:pl-3 sm:pr-2">
          <span className="relative flex size-2.5 shrink-0 items-center justify-center">
            <span className="social-proof-pulse-ring absolute inset-0 rounded-full bg-gold-400" />
            <span className="social-proof-pulse-dot relative size-2.5 rounded-full bg-gold-400" />
          </span>
          <span
            className="max-w-[min(100%,11.5rem)] whitespace-normal text-center text-[12.5px] font-semibold leading-snug text-cream-50 transition-[opacity,transform] duration-500 sm:max-w-none sm:whitespace-nowrap sm:text-[13.5px]"
            style={{
              opacity: phase === "in" ? 1 : 0,
              transform: phase === "in" ? "translateY(0)" : "translateY(-6px)",
              transitionTimingFunction: SPRING,
            }}
          >
            {lineShown}
          </span>
          <button
            type="button"
            onClick={handleDismiss}
            aria-label="Užverti"
            className="ml-auto inline-flex size-11 shrink-0 items-center justify-center rounded-full text-cream-50/75 transition hover:bg-cream-50/10 hover:text-cream-50"
          >
            <X className="block size-3.5 shrink-0" strokeWidth={2.5} />
          </button>
        </div>
        {slice ? (
          <span
            key={pk}
            aria-hidden
            className="social-proof-progress absolute bottom-0 left-0 h-0.5 w-full origin-left"
            style={{ animationDuration: `${displayMs}ms` }}
          />
        ) : null}
      </div>
    </div>
  );
}

"use client";

import dynamic from "next/dynamic";
import Link from "next/link";
import { useEffect, useState } from "react";
import { Heart, Menu, Search, ShoppingBag, X } from "lucide-react";
import { collections } from "@/lib/data/collections";
import { countOf, useCart } from "@/lib/cart/context";
import { useWishlist } from "@/lib/behavior/storage";
import { store } from "@/lib/config/store.config";
import { usePresence } from "@/lib/motion";
import { BrandLogo } from "./brand-logo";
import { SafeDiv } from "./safe-div";

const SearchOverlay = dynamic(
  () => import("./search-overlay").then((m) => ({ default: m.SearchOverlay })),
  { ssr: false }
);

const desktopNav = [
  { href: "/dovanos/visos-dovanos", label: "Kalėdinės dovanos", tone: "text-cranberry-500 hover:text-cranberry-400" },
  { href: "/dovanos/bestselleriai", label: "Bestselleriai", tone: "text-gold-500 hover:text-gold-400" },
  { href: "/dovanos/dovanos-jai", label: "Dovanos jai", tone: "text-rose-500 hover:text-rose-400" },
  { href: "/dovanos/dovanos-jam", label: "Dovanos jam", tone: "text-pine-500 hover:text-pine-400" },
  { href: "/dovanos/dovanos-seimai", label: "Dovanos šeimai", tone: "text-sky-500 hover:text-sky-400" },
  { href: "/dovanos/dovanos-iki-30-euru", label: "Iki 30 €", tone: "text-copper-500" },
];

export function Header() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const [searchMounted, setSearchMounted] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const cart = useCart();
  const wishlist = useWishlist();

  const count = countOf(cart.lines);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 8);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    document.body.style.overflow = menuOpen ? "hidden" : "";
    if (menuOpen) document.documentElement.dataset.menuOpen = "on";
    else delete document.documentElement.dataset.menuOpen;
    return () => {
      document.body.style.overflow = "";
      delete document.documentElement.dataset.menuOpen;
    };
  }, [menuOpen]);

  return (
    <>
      <header
        className={`site-header border-b border-cream-300 bg-cream-50/88 backdrop-blur-md transition-[box-shadow,background-color] duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] ${
          scrolled ? "shadow-lift" : "shadow-card"
